#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> l(n);
    for (int i = 0; i < n; ++i) {
        cin >> l[i];
    }

    vector<int> first_part(l.begin(), l.begin() + n / 2);
    vector<int> second_part(l.begin() + n / 2, l.end());

    int n1 = n / 2;
    int n2 = n / 2 + n % 2;

    int t1 = 1 << n1;
    int t2 = 1 << n2;

    vector<int> s1;
    for (int i = 0; i < t1; ++i) {
        int total = 0;
        for (int j = 0; j < first_part.size(); ++j) {
            if (i & (1 << j)) {
                total += first_part[j];
            }
        }
        s1.push_back(total % m);
    }

    vector<int> s2;
    for (int i = 0; i < t2; ++i) {
        int total = 0;
        for (int j = 0; j < second_part.size(); ++j) {
            if (i & (1 << j)) {
                total += second_part[j];
            }
        }
        s2.push_back(total % m);
    }

    sort(s1.begin(), s1.end());
    sort(s2.begin(), s2.end());

    int max_value = 0;

    auto find_closest = [&](const vector<int>& l, int x) {
        int low = 0;
        int high = (int)l.size() - 1;
        int answer = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (l[mid] < x) {
                answer = l[mid];
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return answer;
    };

    for (int i : s1) {
        int needed = m - i;
        int pair = find_closest(s2, needed);
        max_value = max(max_value, (i + pair) % m);
    }

    cout << max_value << "\n";

    return 0;
}
